package com.mitcampus.ams.controller;
import com.mitcampus.ams.dto.*;import com.mitcampus.ams.dto.Requests.*;import com.mitcampus.ams.service.AmsService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class ApiController {final AmsService s;public ApiController(AmsService s){this.s=s;} @PostMapping("/auth/student/register") @ResponseStatus(HttpStatus.CREATED) ApiResponse rs(@Valid @RequestBody StudentRegistration r){return ApiResponse.ok("Student account created successfully.",s.registerStudent(r));} @PostMapping("/auth/official/register") @ResponseStatus(HttpStatus.CREATED) ApiResponse ro(@Valid @RequestBody OfficialRegistration r){return ApiResponse.ok("Official account created successfully.",s.registerOfficial(r));} @PostMapping("/auth/login") ApiResponse login(@Valid @RequestBody Login r){return ApiResponse.ok("Login successful.",s.login(r));}
 @GetMapping("/officials") ApiResponse officials(@RequestParam(required=false) String department){return ApiResponse.ok("Officials retrieved.",s.officials(department));} @GetMapping("/officials/{id}") ApiResponse official(@PathVariable Long id){return ApiResponse.ok("Official retrieved.",s.profile("official",id));} @GetMapping("/students/{id}") ApiResponse student(@PathVariable Long id){return ApiResponse.ok("Student retrieved.",s.profile("student",id));}
 @PostMapping("/appointments") @ResponseStatus(HttpStatus.CREATED) ApiResponse create(@Valid @RequestBody AppointmentRequest r){return ApiResponse.ok("Appointment request submitted.",s.create(r));} @GetMapping("/appointments/{role}/{id}") ApiResponse appointments(@PathVariable String role,@PathVariable Long id){return ApiResponse.ok("Appointments retrieved.",s.appointmentList(role,id));} @PutMapping("/appointments/{id}/approve") ApiResponse approve(@PathVariable Long id,@Valid @RequestBody Decision r){return ApiResponse.ok("Appointment approved and scheduled.",s.approve(id,r));} @PutMapping("/appointments/{id}/reject") ApiResponse reject(@PathVariable Long id,@RequestBody Reject r){return ApiResponse.ok("Appointment rejected.",s.reject(id,r));}
 @GetMapping("/notifications/{id}") ApiResponse notes(@PathVariable Long id){return ApiResponse.ok("Notifications retrieved.",s.notificationList(id));} @PutMapping("/notifications/{id}/read-all") ApiResponse read(@PathVariable Long id){s.readAll(id);return ApiResponse.ok("Notifications marked as read.",null);} @GetMapping("/availability/{id}") ApiResponse availabilityList(@PathVariable Long id){return ApiResponse.ok("Availability retrieved.",s.availability(id));} @PutMapping("/availability/official/{id}") ApiResponse availability(@PathVariable Long id,@RequestBody AvailabilitySave r){s.saveAvailability(id,r);return ApiResponse.ok("Availability saved.",null);} @GetMapping("/dashboard/{role}/{id}") ApiResponse dash(@PathVariable String role,@PathVariable Long id){return ApiResponse.ok("Dashboard retrieved.",s.dashboard(role,id));}}
